// Local websites photographed by the real server-side capture path. All names,
// content and imagery are synthetic; the pictures are screenshots, not mockups.
export const previewNames = ['Atlas', 'Atlas-bench', 'Atlas-demo', 'Atlas-design', 'Atlas-maps', 'A little weather', 'Reading room', 'Kitchen notes', 'Signal wall', 'Notebook', 'Playground']
export const mark = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="14" fill="#384e72"/><path d="M15 16h14q8 0 8 8v26q-4-7-10-7H15Zm34 0H37v34q4-7 10-7h2Z" fill="#f0e5c9"/></svg>'
const leaves = '<svg viewBox="0 0 480 380"><g fill="#55745b"><path d="M240 340C69 286 49 138 83 65c123 13 206 116 157 275Z"/><path d="M245 308c-3-151 100-244 197-244 5 134-78 237-197 244Z"/></g><path d="m239 355 8-266m-9 253L113 111m129 200L401 103" fill="none" stroke="#e1d8b2" stroke-width="6"/></svg>'
const chart = '<svg viewBox="0 0 600 280"><path d="M0 230H600M0 155H600M0 80H600" stroke="#d5dfe9"/><path d="M0 238 70 202 120 214 190 145 260 162 320 95 380 110 450 61 520 76 600 18V280H0Z" fill="#d8e6f5"/><path d="m0 238 70-36 50 12 70-69 70 17 60-67 60 15 70-49 70 15 80-58" fill="none" stroke="#4773ab" stroke-width="7" stroke-linecap="round"/></svg>'
const map = '<svg viewBox="0 0 600 400"><path d="M0 0h600v400H0Z" fill="#dbe4d5"/><path d="m0 85 600 170M90 0 160 400M380 0 300 400M0 310 600-130" stroke="#f6f3df" stroke-width="30"/><path d="m0 305 196-110 85 52 319-97" stroke="#699391" stroke-width="12" fill="none"/><circle cx="281" cy="247" r="22" fill="#a6513d" stroke="#faf6e6" stroke-width="7"/></svg>'
const css = `*{box-sizing:border-box}body{margin:0;color:#283a36;background:#f5f2e8;font:18px Arial,sans-serif}header{display:flex;align-items:center;justify-content:space-between;padding:26px 62px;border-bottom:1px solid #24392c22;font-size:16px}header strong{font:26px Georgia}nav{display:flex;align-items:center;gap:30px;color:#69736b}button{border:0;border-radius:50px;background:#e3e7dc;padding:10px 17px;color:inherit}main{padding:48px 62px}h1{font:64px/1.06 Georgia;margin:12px 0 22px;letter-spacing:-2px}h2{font:28px Georgia;margin:0 0 14px}p{line-height:1.6;color:#657169}.eyebrow{font-size:12px;letter-spacing:3px;text-transform:uppercase}.hero{display:grid;grid-template-columns:1fr 1fr;align-items:center;gap:60px}.art{border-radius:28px;background:#e8e4cf;padding:26px;height:360px;overflow:hidden}.art svg{width:100%;height:100%}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:32px}.card{padding:28px;border:1px solid #263b3022;border-radius:18px;background:#fffdf5}.card p{font-size:15px;margin-bottom:0}.number{font:52px Georgia;margin:16px 0}.pill{display:inline-block;border-radius:100px;padding:10px 18px;background:#355647;color:#fff;font-size:14px}.blue{background:#edf2f8;color:#283c57}.blue p{color:#64728a}.blue .art{background:#f9fbff;border:1px solid #d9e2ee}.blue .card{background:#f9fbff}.purple{background:#ede8f1;color:#493e58}.purple .art{background:#584866;color:#f2e7d5;display:flex;align-items:center;justify-content:center;font:130px Georgia}.purple .card{background:#f8f4fa}.sun{background:#f8edd8;color:#594631}.sun .art{background:#e8c072}.sun .card{background:#fff7e8}.recipe{background:#f2e5da;color:#603f34}.recipe .art{background:#bf7456}.recipe .card{background:#fbf3e9}`
export function previewPage(index) {
  if (index === 8) return '<!doctype html><meta charset="utf-8"><style>html,body{margin:0;background:#151515}canvas{width:100vw;height:100vh}</style><canvas width="1280" height="800"></canvas>'
  const name = previewNames[index] ?? 'A small app'
  let theme = '', title = 'A place for your next idea.', eyebrow = 'A personal workspace', description = 'Collect what matters. Make room for what comes next.', art = leaves, cards = ['Make a little space', 'Follow a good question', 'Keep the useful things']
  if ([0, 2, 10].includes(index)) { theme = 'blue'; title = index === 0 ? 'A clear view of<br>what comes next.' : index === 2 ? 'Small ideas.<br>Real possibilities.' : 'Make something<br>worth exploring.'; eyebrow = 'Projects, in perspective'; art = chart; cards = ['12 active projects', '36 notes connected', 'A little progress, daily'] }
  if (index === 4) { title = 'Find your<br>own way there.'; eyebrow = 'Places worth keeping'; art = map; cards = ['Near and familiar', 'Further afield', 'Somewhere new'] }
  if (index === 5) { theme = 'sun'; title = 'A good day<br>to be outside.'; eyebrow = 'Today, at a glance'; art = '<svg viewBox="0 0 500 340"><g stroke="#a96b36" fill="none" stroke-width="5"><circle cx="250" cy="155" r="75"/><path d="M250 25v-20m0 280v20M120 155H95m310 0h-25M155 60l-18-18m226 226-18-18m0-190 18-18M155 250l-18 18"/></g><text x="250" y="310" text-anchor="middle" font-size="42" fill="#80502b">24° · A gentle breeze</text></svg>'; cards = ['Morning light', 'A slower afternoon', 'Clear skies tonight'] }
  if ([6, 9].includes(index)) { theme = 'purple'; title = index === 6 ? 'A few good words.<br>A little more time.' : 'Leave a thought.<br>Find it again.'; eyebrow = 'Notes from the margins'; art = 'Aa'; cards = ['On the reading list', 'The idea to return to', 'A sentence worth saving'] }
  if (index === 7) { theme = 'recipe'; title = 'Something simple.<br>Something shared.'; eyebrow = 'From the kitchen'; art = '<svg viewBox="0 0 500 340"><ellipse cx="250" cy="180" rx="145" ry="105" fill="#f9e9c9"/><ellipse cx="250" cy="180" rx="118" ry="80" fill="#ddd6ad"/><g fill="#617b4d"><ellipse cx="221" cy="166" rx="64" ry="24" transform="rotate(-25 221 166)"/><ellipse cx="278" cy="190" rx="64" ry="24" transform="rotate(25 278 190)"/></g><circle cx="253" cy="165" r="27" fill="#bb5b3f"/></svg>'; cards = ['A weeknight favourite', 'Something for the table', 'The recipe notebook'] }
  return `<!doctype html><meta charset="utf-8">${index === 6 ? '<link rel="icon" href="/mark.svg">' : ''}<style>${css}</style><body class="${theme}"><header><strong>${name}</strong><nav>Overview <span>Collections</span><button id="counter" onclick="this.textContent=String(parseInt(this.textContent)+1)">0 saved</button></nav></header><main><div class="hero"><section><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p><span class="pill">Take a look around ↗</span></section><div class="art">${art}</div></div><div class="cards">${cards.map((label, i) => `<div class="card"><div class="eyebrow">0${i + 1}</div><h2>${label}</h2><p>A little room to think, collect and make.</p></div>`).join('')}</div></main>`
}
